                                                                                                                                                                                                       
  CREATE TABLE "TENANT_NOTIFY"                                                                                                                                                              
   (	"NOTIFY_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                 
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                   
	"UPDATED_BY" NUMBER,                                                                                                                                                                                  
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                   
	"IS_ALL" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                            
	"IMPORTANCE_LEVEL" NVARCHAR2(10) DEFAULT 'NORMAL' NOT NULL ENABLE,                                                                                                                                    
	"TITLE" NVARCHAR2(100) NOT NULL ENABLE,                                                                                                                                                               
	"SORT_CONTENT" NVARCHAR2(255) NOT NULL ENABLE,                                                                                                                                                        
	"CONTENT" CLOB NOT NULL ENABLE,                                                                                                                                                                       
	"CONTENT_LANG" NVARCHAR2(20) DEFAULT 'HTML' NOT NULL ENABLE,                                                                                                                                          
	"SORT_NUM" NUMBER(20,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                    
	"BUTTON_LINK_URL" NVARCHAR2(255),                                                                                                                                                                     
	"BUTTON_DISPLAY_NAME" NVARCHAR2(20),                                                                                                                                                                  
	"IS_DISPLAY_BUTTON" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                 
	"NOTIFY_TYPE" NVARCHAR2(100) DEFAULT 'NORMAL',                                                                                                                                                        
	"VERSION_NUMBER" NVARCHAR2(30),                                                                                                                                                                       
	"ROBOT_SUBSCRIBE_RANGE" NVARCHAR2(500),                                                                                                                                                               
	"IS_XJ_SEND" NUMBER DEFAULT 0,                                                                                                                                                                        
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                         
	 PRIMARY KEY ("NOTIFY_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                  
   ) ;                                                                                                                                                                                                 

